    TEST_ASSERT_EQUAL(0, at("cubic-bezier(0.13, 1, 0.7, 0)", 0, 0));
    TEST_ASSERT_EQUAL(5002, at("cubic-bezier(0.13, 1, 0.7, 0)", 4765, 0));
    TEST_ASSERT_EQUAL(10000, at("cubic-bezier(0.13, 1, 0.7, 0)", 10000, 0));
